CREATE TABLE IF NOT EXISTS "schema_migrations" ("version" text PRIMARY KEY, "applied_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "settings" ("id" integer PRIMARY KEY DEFAULT 1, "server_name" text NOT NULL DEFAULT 'MeteoHub', "calibration_enabled" boolean NOT NULL DEFAULT true, "ingestion_enabled" boolean NOT NULL DEFAULT false, "raw_retention_days" integer NOT NULL DEFAULT 365, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "devices" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL, "token_hash" text NOT NULL, "last_seen_at" timestamptz, "revoked_at" timestamptz, "sync_cursor" integer NOT NULL DEFAULT 0, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "devices_token_hash_idx" ON "devices" ("token_hash");
CREATE TABLE IF NOT EXISTS "pairing_codes" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "code_hash" text NOT NULL, "code_hint" varchar(4) NOT NULL, "expires_at" timestamptz NOT NULL, "used_at" timestamptz, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "hub_locations" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "name" text NOT NULL, "latitude" real NOT NULL, "longitude" real NOT NULL, "timezone" text NOT NULL, "country_code" varchar(2), "admin1" text, "admin2" text, "alias" text, "sort_order" integer NOT NULL DEFAULT 0, "analysis_enabled" boolean NOT NULL DEFAULT true, "deleted_at" timestamptz, "sync_version" integer NOT NULL DEFAULT 0, "fallback_provider" text NOT NULL DEFAULT 'open-meteo', "raw_retention_days" integer NOT NULL DEFAULT 365, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "sync_changes" ("version" serial PRIMARY KEY, "entity" text NOT NULL, "entity_id" uuid NOT NULL, "operation" text NOT NULL, "payload" jsonb, "occurred_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "forecast_runs" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(), "location_id" uuid NOT NULL, "model_id" text NOT NULL, "run_at" timestamptz NOT NULL, "fetched_at" timestamptz NOT NULL, "source_version" text NOT NULL, "request_key" text NOT NULL, "metadata" jsonb NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX IF NOT EXISTS "forecast_runs_request_key_idx" ON "forecast_runs" ("request_key");
CREATE TABLE IF NOT EXISTS "forecast_values" ("id" serial PRIMARY KEY, "run_id" uuid NOT NULL, "location_id" uuid NOT NULL, "model_id" text NOT NULL, "run_at" timestamptz NOT NULL, "valid_at" timestamptz NOT NULL, "lead_hours" integer NOT NULL, "variable" text NOT NULL, "value" numeric, "source_version" text NOT NULL, "metadata" jsonb NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX IF NOT EXISTS "forecast_values_identity_idx" ON "forecast_values" ("location_id", "model_id", "run_at", "valid_at", "variable");
CREATE TABLE IF NOT EXISTS "observations" ("id" serial PRIMARY KEY, "location_id" uuid NOT NULL, "observed_at" timestamptz NOT NULL, "variable" text NOT NULL, "value" numeric, "provider" text NOT NULL, "source_version" text NOT NULL);
CREATE UNIQUE INDEX IF NOT EXISTS "observations_identity_idx" ON "observations" ("location_id", "observed_at", "variable", "provider");
CREATE TABLE IF NOT EXISTS "verification_scores" ("id" serial PRIMARY KEY, "location_id" uuid NOT NULL, "model_id" text NOT NULL, "variable" text NOT NULL, "lead_hours" integer NOT NULL, "score_date" timestamptz NOT NULL, "mae" real, "bias" real, "brier_score" real, "hits" integer NOT NULL DEFAULT 0, "misses" integer NOT NULL DEFAULT 0, "false_alarms" integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS "calibration_parameters" ("id" serial PRIMARY KEY, "location_id" uuid NOT NULL, "model_id" text NOT NULL, "variable" text NOT NULL, "lead_band" integer NOT NULL, "bias" real NOT NULL, "sample_count" integer NOT NULL, "max_correction" real NOT NULL, "model_version" text NOT NULL, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS "fused_forecasts" ("location_id" uuid PRIMARY KEY, "generated_at" timestamptz NOT NULL, "timezone" text NOT NULL, "payload" jsonb NOT NULL, "source_runs" jsonb NOT NULL DEFAULT '[]');
CREATE TABLE IF NOT EXISTS "ingestion_jobs" ("id" serial PRIMARY KEY, "job_key" text NOT NULL, "location_id" uuid, "provider" text NOT NULL, "status" text NOT NULL, "attempts" integer NOT NULL DEFAULT 0, "started_at" timestamptz, "finished_at" timestamptz, "error" text, "created_at" timestamptz NOT NULL DEFAULT now(), "updated_at" timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS "ingestion_jobs_job_key_idx" ON "ingestion_jobs" ("job_key");
INSERT INTO "schema_migrations" ("version") VALUES ('0000_initial') ON CONFLICT DO NOTHING;
